 * - revert: 회귀 — revertTo(생략 시 1단계) 로 점프. clamp 상한 = stage-1(앞으로만).
 *   validThrough = target-1(target 단계 산출물부터 무효). Stage 1에서는 no-op.
 */
export function applyVerdict(
	state: PipelineState,
	decision: GateDecision,
	now = Date.now(),
): PipelineState {
	const { verdict } = decision;
	const withHistory = record(state, verdict, now);

	if (verdict === "modify") {
		return {
			...withHistory,
			gateOpen: false,
			loopCount: state.loopCount + 1,
			updatedAt: now,
		};
	}

	if (verdict === "revert") {
		// FR-7: 여러 단계 점프 회귀. 현재 단계보다 앞으로만(clamp 상한 = stage-1).
		const target = clamp(
			decision.revertTo ?? state.stage - 1,
			1,
			state.stage - 1,
		) as StageId;
		return {
			...withHistory,
			stage: target,
			gateOpen: false,
			loopCount: 0,
			validThrough: (target - 1) as ValidThrough,
			updatedAt: now,
		};
	}

	// confirm: 한 단계 승인 = 그 단계까지 유효.
	const confirmedValid = Math.max(
		state.validThrough,
		state.stage,
	) as ValidThrough;
	if (state.stage >= 3) {
		return {
			...withHistory,
			stage: 3,
			gateOpen: false,
			done: true,
			validThrough: confirmedValid,
			updatedAt: now,
		};
	}
	const next = (state.stage + 1) as StageId;
	return {
		...withHistory,
		stage: next,
		gateOpen: false,
		loopCount: 0,
		validThrough: confirmedValid,
		updatedAt: now,
	};
